  summary = 'The course teaches the syntax-semantics distinction, proof strategy, model construction, enough set theory to understand semantics, and how first-order logic connects to modal logic, nonclassical logic, computation, and philosophical analysis.',
  data = $slogjson${"slug": "symbolic-logic", "title": "Symbolic Logic", "description": "The course teaches the syntax-semantics distinction, proof strategy, model construction, enough set theory to understand semantics, and how first-order logic connects to modal logic, nonclassical logic, computation, and philosophical analysis.", "topics": [{"id": "1c390f4b-5604-4d6b-82a9-423192635fff", "type": "topic", "title": "Formal Languages, Syntax, Semantics, and Use", "description": "Establish symbolic logic as the study of formal languages, interpretation, consequence, and rigorous argument.", "children": [{"id": "787f6dac-e6a7-4450-b7aa-7e90cf9facc2", "type": "subtopic", "title": "Formalization and abstraction", "children": [{"id": "b399a6b8-99d8-4de4-aeb7-daac5a30fe62", "type": "concept", "title": "Object language and metalanguage"}, {"id": "ffd4d342-9eb2-4c38-8007-21c7c26b5f1e", "type": "concept", "title": "Formal vocabulary"}, {"id": "c85f3b1f-bf9e-425c-a3d5-d5d91ddbcc97", "type": "concept", "title": "Well-formed formulas"}, {"id": "5030b547-82f6-4746-b819-d23865141cb2", "type": "concept", "title": "Abstraction from content"}], "description": "Students learn why logic replaces ordinary-language clutter with precise symbols while preserving inferential structure."}, {"id": "488198d9-34c5-41d8-be2c-2bfc91732762", "type": "subtopic", "title": "Syntax versus semantics", "children": [{"id": "972db581-b853-41ae-a397-ba7b453233d4", "type": "concept", "title": "Formation rules"}, {"id": "ea3b3948-31e6-48f0-9ad7-4238f65af81b", "type": "concept", "title": "Interpretations"}, {"id": "bb9d1efb-5141-455a-ae3d-9ca6fe4cb358", "type": "concept", "title": "Truth conditions"}, {"id": "cab7a856-5f64-435c-bbb6-5af13201cb5d", "type": "concept", "title": "Consequence"}], "description": "This distinction is the course's spine: syntax concerns formation and proof; semantics concerns truth and interpretation."}, {"id": "189313b2-8fda-49a0-a733-18cd97cbc7d2", "type": "subtopic", "title": "Logic in philosophy and mathematics", "children": [{"id": "05c34a5b-332d-405f-91b1-a1ed09b4fdef", "type": "concept", "title": "Philosophical arguments"}, {"id": "9b4ce1e4-5714-482a-93bf-d84816d14521", "type": "concept", "title": "Mathematical proof"}, {"id": "04764f93-d5ac-461c-b7d1-9b3f7ba90b74", "type": "concept", "title": "Computer science links"}, {"id": "c6088f06-f78e-47fb-9f29-a2af210b8f5d", "type": "concept", "title": "Limits of formalization"}], "description": "Symbolic logic is both a tool for argument analysis and a foundation for mathematics, computation, and language."}]}, {"id": "d59836cc-91c6-4b63-8421-f9530f69acef", "type": "topic", "title": "Propositional Logic: Connectives, Truth Conditions, and Translation", "description": "Learn how ordinary claims can be represented with truth-functional structure.", "children": [{"id": "a9c9bf4c-ad13-4ce5-9c84-8c6bc1211db0", "type": "subtopic", "title": "Atomic and compound sentences", "children": [{"id": "b97ae975-cd9b-4290-b043-cfbd7a3b9dbd", "type": "concept", "title": "Atomic propositions"}, {"id": "a0fda7ec-b0d1-45b2-8ec3-ba268e925eec", "type": "concept", "title": "Negation"}, {"id": "ad440e22-4054-4548-bb83-7ce1c49daafa", "type": "concept", "title": "Conjunction and disjunction"}, {"id": "8298bec8-355a-4f96-8e68-7507b1e78b71", "type": "concept", "title": "Conditionals and biconditionals"}], "description": "Students begin with sentence letters and truth-functional connectives as the basic grammar of propositional logic."}, {"id": "273311e2-9805-4f40-abe4-205e0f7c5f4a", "type": "subtopic", "title": "Truth-functional meaning", "children": [{"id": "fc2a8b52-6e8f-4c16-9086-5b41677a0774", "type": "concept", "title": "Truth conditions"}, {"id": "9c3710a6-6040-4dda-959f-9861917d7074", "type": "concept", "title": "Inclusive or"}, {"id": "3957a12f-897a-44f2-a228-92bcf5790a46", "type": "concept", "title": "Material conditional"}, {"id": "a5683586-6518-4bed-a650-bc7541776a6f", "type": "concept", "title": "Biconditional equivalence"}], "description": "The point is to see how compound truth depends only on the truth values of its parts."}, {"id": "27e9098a-7116-451d-b619-3ddf4dedf075", "type": "subtopic", "title": "Translation from English", "children": [{"id": "3233a806-4cf0-4e2e-9355-e175d1f5b9f5", "type": "concept", "title": "Necessary and sufficient conditions"}, {"id": "e705d2c2-7a59-4504-85cc-265d1d237c12", "type": "concept", "title": "Unless"}, {"id": "7a67a0f7-690d-430f-97ef-b76f57f8ea0a", "type": "concept", "title": "Only if"}, {"id": "2f78df20-ad6b-41f0-8a44-e8ac3c093bfc", "type": "concept", "title": "Ambiguity and paraphrase"}], "description": "Translation trains students to separate logical form from rhetoric, emphasis, and conversational implication."}]}, {"id": "18ed7598-511d-4bcf-8bec-8cc2a022cb30", "type": "topic", "title": "Truth Tables, Tautologies, Contradictions, and Logical Equivalence", "description": "Use semantic calculation to test validity, consistency, satisfiability, and equivalence.", "children": [{"id": "1ea8e2cc-d7b4-4a56-b7b5-17fcc2686ee2", "type": "subtopic", "title": "Full and partial truth tables", "children": [{"id": "61c8be27-4b8a-4855-bfbc-9a15c0ddcc83", "type": "concept", "title": "Truth-value assignments"}, {"id": "6e51539c-9722-4896-83a2-9a078452d09a", "type": "concept", "title": "Main connective"}, {"id": "97e0f8f0-ec22-4eeb-967d-022dacb30508", "type": "concept", "title": "Short truth tables"}, {"id": "548376e6-6981-4dd8-bf27-78bcd0dae09e", "type": "concept", "title": "Semantic counterexamples"}], "description": "Truth tables give a mechanical semantic method for testing formulas and arguments."}, {"id": "53ed2431-9c61-45a8-850a-e146e2b1dfe4", "type": "subtopic", "title": "Semantic classifications", "children": [{"id": "80e0285d-feff-4c3e-b1f4-500adb120174", "type": "concept", "title": "Tautology"}, {"id": "32cf589b-ea9d-497b-912c-f21cb2e0207d", "type": "concept", "title": "Contradiction"}, {"id": "9a6e18a6-bd82-4f8c-ac29-ad2a6115f6d3", "type": "concept", "title": "Contingency"}, {"id": "e23c8704-d0e8-43e6-8adc-3e3ee05bd62d", "type": "concept", "title": "Satisfiability"}], "description": "Students learn the key status terms that organize propositional reasoning."}, {"id": "d88cebc0-bbb1-4d5c-89db-099f54629a42", "type": "subtopic", "title": "Argument validity and equivalence", "children": [{"id": "8c16099e-1371-484c-8e4f-caf928cb88cd", "type": "concept", "title": "Validity"}, {"id": "157a2a6e-6243-49b6-af80-5a7c1ef6dafa", "type": "concept", "title": "Invalidity"}, {"id": "38bb7455-84ac-436f-bf11-a5a9faf3b9dd", "type": "concept", "title": "Logical equivalence"}, {"id": "a00a719f-b372-4d6a-a2f6-3b0d30b10fe9", "type": "concept", "title": "Consistency of sets"}], "description": "Validity becomes a precise semantic relation, not a matter of persuasion or plausibility."}]}, {"id": "523cc7d0-101b-49b5-ba2d-664ddb757c4b", "type": "topic", "title": "Natural Deduction for Propositional Logic", "description": "Build disciplined proof habits through introduction and elimination rules.", "children": [{"id": "a8fe6e01-e12a-4430-9f43-fcf154b43c90", "type": "subtopic", "title": "Introduction and elimination rules", "children": [{"id": "6aa38ee4-3b1b-4787-bcf5-bef899b02bd5", "type": "concept", "title": "And rules"}, {"id": "3544bd6a-149c-4dd2-bbfc-795d2006be7f", "type": "concept", "title": "Or rules"}, {"id": "c570a280-3298-45ed-bd9d-2fa16b0d90bb", "type": "concept", "title": "Conditional rules"}, {"id": "11702e71-006c-44a3-8385-7fa0d63e5e7c", "type": "concept", "title": "Negation rules"}], "description": "Natural deduction teaches students to reason by the meaning of each connective."}, {"id": "48ab826a-c5d5-43c6-ac11-7d12af6ba6d6", "type": "subtopic", "title": "Assumptions and subproofs", "children": [{"id": "11ef4f95-c4a0-4b3c-bcf5-424094a2feec", "type": "concept", "title": "Conditional proof"}, {"id": "05814e5b-f3e9-418f-a600-246fbf7a0fc5", "type": "concept", "title": "Indirect proof"}, {"id": "17c423ff-8449-452e-82da-5090ac68b83a", "type": "concept", "title": "Proof by cases"}, {"id": "28f01922-83b9-4aea-a6b0-66cf3f305412", "type": "concept", "title": "Discharging assumptions"}], "description": "Subproofs let students reason conditionally, indirectly, and by cases."}, {"id": "2f642071-0f7b-442f-8a25-780fff0893bc", "type": "subtopic", "title": "Proof checking", "children": [{"id": "ca1b61ef-9224-4c02-9d71-45cd810067f2", "type": "concept", "title": "Line numbers"}, {"id": "0eaf4e3c-58e5-46a2-aff4-26951565320e", "type": "concept", "title": "Justifications"}, {"id": "db15a793-0ddf-4eee-9b85-4657b97ce104", "type": "concept", "title": "Dependency tracking"}, {"id": "4a2a18f2-4399-409b-83f4-7d1e8b9e5e4d", "type": "concept", "title": "Common proof errors"}], "description": "Proofs are public objects whose validity depends on line-by-line rule application."}]}, {"id": "963d66ad-ec23-4201-8b29-09687d2b33a9", "type": "topic", "title": "Proof Strategies, Derived Rules, and Metatheoretic Awareness", "description": "Move from rule-following to strategic proof construction and reflection on proof systems.", "children": [{"id": "d8dbfcd3-f736-4a3b-a8dd-23e7c797d0bd", "type": "subtopic", "title": "Strategic proof planning", "children": [{"id": "ca603013-bdb9-4a5a-a9c4-8c64c383bfd1", "type": "concept", "title": "Goal analysis"}, {"id": "4d402b77-de1a-439c-a8ff-008dddebd058", "type": "concept", "title": "Premise exploitation"}, {"id": "5b6c8e14-7c62-42f4-9883-b4f3676033d9", "type": "concept", "title": "Subgoal creation"}, {"id": "31973cb7-0769-402a-a36a-e7fd0b147d92", "type": "concept", "title": "Proof search"}], "description": "Students move from trying random rules to planning backwards from the goal and forwards from available premises."}, {"id": "ec8cb2e7-9010-4b4f-b3ff-a8f3a58dfe4e", "type": "subtopic", "title": "Derived rules and equivalences", "children": [{"id": "94a7cc9c-db96-4223-ad91-fe8842d733a2", "type": "concept", "title": "Double negation"}, {"id": "14846870-7543-4e9a-b6cf-1f8164882f5c", "type": "concept", "title": "De Morgan laws"}, {"id": "033f3c5a-a7eb-407a-9dd2-2123dffbb114", "type": "concept", "title": "Modus tollens"}, {"id": "89428ada-4b04-4f37-bdfd-9a5da3d09022", "type": "concept", "title": "Hypothetical syllogism"}], "description": "Derived tools make proofs efficient while preserving rigor."}, {"id": "13456f9c-3e5f-40bf-9823-83de06ff7e08", "type": "subtopic", "title": "Proof systems as objects of study", "children": [{"id": "129b7581-2ff8-46f2-9089-c1fefd3b75f7", "type": "concept", "title": "Derivability"}, {"id": "ddeddc81-71e1-45c5-94c2-25b766cda997", "type": "concept", "title": "Theorems"}, {"id": "2cb81986-08ea-450b-a9c0-b126cc2d11ed", "type": "concept", "title": "Soundness idea"}, {"id": "4fd730a9-d2fb-4461-b031-4bcc53ee6b10", "type": "concept", "title": "Completeness idea"}], "description": "Metatheory begins when students ask what a proof system can and cannot prove."}]}, {"id": "45b081f4-dd0f-44e5-9fd9-ade0e5fb7473", "type": "topic", "title": "Predicate Logic: Predicates, Variables, Quantifiers, and Scope", "description": "Represent generality, relations, and quantified reasoning with first-order notation.", "children": [{"id": "1c9f0c39-9dc1-4a5d-95b7-2ab259bcd556", "type": "subtopic", "title": "Predicates and relations", "children": [{"id": "d661c75b-4daa-4136-a769-76f6e2985a15", "type": "concept", "title": "One-place predicates"}, {"id": "4b9b3e8b-8413-4890-9b9a-104d38c7d316", "type": "concept", "title": "Relations"}, {"id": "5db41806-9242-4eb3-8b65-488d09a221b3", "type": "concept", "title": "Constants"}, {"id": "7ee877c6-fd72-4a05-bcaa-70793a4fe32a", "type": "concept", "title": "Variables"}], "description": "Predicate logic captures internal sentence structure that propositional logic cannot see."}, {"id": "b3f93305-d753-4016-b85d-1678dbb06650", "type": "subtopic", "title": "Quantification", "children": [{"id": "29f4fb09-652b-45c3-9a32-5e6906fb173c", "type": "concept", "title": "Universal quantifier"}, {"id": "2f9ad9b8-3fa5-488a-824a-0da38b563bca", "type": "concept", "title": "Existential quantifier"}, {"id": "d3289105-fec4-497e-82d1-e305c7158610", "type": "concept", "title": "Nested quantifiers"}, {"id": "adc9cf28-96e3-4ae5-8d83-a5c46f60a8ba", "type": "concept", "title": "Quantifier order"}], "description": "Quantifiers allow formal treatment of generality, existence, and mixed claims."}, {"id": "1e8390df-2f04-426f-a3f9-01b9e0877dfe", "type": "subtopic", "title": "Scope and binding", "children": [{"id": "1a34441f-9012-4ebf-ba1f-3f5f7c58a033", "type": "concept", "title": "Bound variables"}, {"id": "67ece5da-b118-4aea-a262-090d472528f0", "type": "concept", "title": "Free variables"}, {"id": "503ca36e-79c6-4209-97af-c29f7f413ebc", "type": "concept", "title": "Scope ambiguity"}, {"id": "cdc4318c-4c19-43fb-b649-1b1ee049c126", "type": "concept", "title": "Variable renaming"}], "description": "Most predicate-logic mistakes are scope mistakes, so students learn to track exactly what each quantifier governs."}]}, {"id": "ba9a776c-2f92-47a1-9da8-d74f9135fc11", "type": "topic", "title": "Identity, Definite Descriptions, and Relational Structure", "description": "Handle sameness, uniqueness, numerical claims, and relational patterns precisely.", "children": [{"id": "d7e30730-7e3b-4137-9eaa-766242315ca6", "type": "subtopic", "title": "Identity logic", "children": [{"id": "46a827b2-dd01-4d2f-bc0d-ac1af27e1635", "type": "concept", "title": "Equals"}, {"id": "73fb22f9-044e-4289-b7d3-75f0e182f0b3", "type": "concept", "title": "Not identical"}, {"id": "254c00b4-cf69-4da7-9bbc-62a404fa32d3", "type": "concept", "title": "At least and at most"}, {"id": "b214eecc-a91c-4995-8092-591e615ceab4", "type": "concept", "title": "Exactly one"}], "description": "Identity lets students formalize sameness, distinctness, uniqueness, and counting."}, {"id": "9d993997-67d9-418a-b291-f3b33a9a2f90", "type": "subtopic", "title": "Descriptions and uniqueness", "children": [{"id": "f330c29a-bed5-4260-9698-e745905645bb", "type": "concept", "title": "The F"}, {"id": "8d54de66-a04b-4d92-8177-38d6b1bad07a", "type": "concept", "title": "Existence"}, {"id": "c64220b8-e085-453e-b38d-e087487f25e9", "type": "concept", "title": "Uniqueness"}, {"id": "441e7b84-28a4-429a-abb2-4691a7869207", "type": "concept", "title": "Russell-style analysis"}], "description": "Definite descriptions reveal how ordinary phrases can hide existential and uniqueness commitments."}, {"id": "abe9757b-4059-4156-a698-879f88cd164c", "type": "subtopic", "title": "Relational patterns", "children": [{"id": "2dc483c2-ff17-46d2-b659-ec0f2bbac0cc", "type": "concept", "title": "Reflexivity"}, {"id": "e7c42632-fef1-4150-9049-3f068809bc08", "type": "concept", "title": "Symmetry"}, {"id": "508ecad7-204c-4f6e-a13c-fe81dcefe628", "type": "concept", "title": "Transitivity"}, {"id": "dd0700b4-1a41-4b86-a7a7-def40f666d1f", "type": "concept", "title": "Ordering relations"}], "description": "Relations let logic express structure, order, dependence, and social or mathematical arrangements."}]}, {"id": "8029cc50-1a6a-404d-aa3a-66c9e535372f", "type": "topic", "title": "Natural Deduction for Predicate Logic", "description": "Extend formal proof to quantifiers while respecting restrictions on arbitrary names and variables.", "children": [{"id": "b55616ec-1910-4e93-9a5b-7d0d57618da4", "type": "subtopic", "title": "Quantifier rules", "children": [{"id": "aa992ba3-9a26-4dd5-8668-2658b3dc0502", "type": "concept", "title": "Universal elimination"}, {"id": "ec577c72-e007-4ad4-b281-46db91208f5b", "type": "concept", "title": "Universal introduction"}, {"id": "1fc13e1d-a412-4a87-80f7-68fa539ac4a6", "type": "concept", "title": "Existential introduction"}, {"id": "7a0796a0-3b97-4946-89cd-e55c08feded5", "type": "concept", "title": "Existential elimination"}], "description": "Students learn how universal and existential claims enter and leave proofs."}, {"id": "14f3903b-23f9-4924-91d9-b41af62ba351", "type": "subtopic", "title": "Restrictions on variables and names", "children": [{"id": "d5955336-34c3-478d-99b5-21995101585d", "type": "concept", "title": "Arbitrary names"}, {"id": "1c9bac5c-ecb0-4351-ba5b-b610eb25b35b", "type": "concept", "title": "Fresh constants"}, {"id": "7d3557d5-f59e-445f-ab10-a3f8a3dc787d", "type": "concept", "title": "Free-for substitution"}, {"id": "918fbf24-3b4f-4796-8f13-57ae436d1c10", "type": "concept", "title": "Variable capture"}], "description": "The technical restrictions protect proofs from illicit generalization."}, {"id": "d25110db-ef80-4708-9733-a23296e02d57", "type": "subtopic", "title": "Mixed proofs with identity", "children": [{"id": "9fb5bf37-512f-4afa-b531-a8573f874e19", "type": "concept", "title": "Leibniz substitution"}, {"id": "caabf637-3705-4f99-aac3-0e65d7132e82", "type": "concept", "title": "Uniqueness proofs"}, {"id": "6677b0d6-2017-45c9-823d-aca81afd51c7", "type": "concept", "title": "Nested subproofs"}, {"id": "c5fd8034-f067-4c39-80f1-f2326bca7a71", "type": "concept", "title": "Counterexample-guided proof planning"}], "description": "Real proofs combine quantifiers, connectives, relations, and identity rather than isolating them."}]}, {"id": "2cb9ba1f-e1e7-4bb7-8abe-04610d22bf05", "type": "topic", "title": "Models, Interpretations, Truth in a Structure, and Validity", "description": "Understand semantic consequence through domains, interpretations, countermodels, and structures.", "children": [{"id": "1db918df-38be-41b8-bfd7-631e193b6e15", "type": "subtopic", "title": "Structures and interpretations", "children": [{"id": "d86ca9a9-8704-4fb6-a0a0-4592f62a2207", "type": "concept", "title": "Domains"}, {"id": "273c7951-141e-483c-b0af-c80d8a353dfc", "type": "concept", "title": "Extensions"}, {"id": "f1a1c52e-feea-4ded-89e9-8c92df196242", "type": "concept", "title": "Interpretation functions"}, {"id": "4409b40e-e86a-43a5-a62b-78045942ad3c", "type": "concept", "title": "Assignments"}], "description": "Model theory gives semantics for predicate logic by assigning domains, objects, properties, and relations."}, {"id": "3023b320-169f-49cb-9347-9d37d6f524d4", "type": "subtopic", "title": "Truth in a model", "children": [{"id": "c31db9cd-6ca5-44f7-abb9-68bd25071a58", "type": "concept", "title": "Satisfaction"}, {"id": "cb1d67bb-343f-45e1-9c66-494dfcaed188", "type": "concept", "title": "Truth definition"}, {"id": "84c877eb-65a3-45d7-99e1-ce0923fe06b7", "type": "concept", "title": "Open formulas"}, {"id": "cedc131a-0f3f-4092-bfa5-bdc5c02bd75c", "type": "concept", "title": "Sentences"}], "description": "Students learn how a formula becomes true or false relative to a structure and variable assignment."}, {"id": "e5707751-b7c2-4b5f-b5d6-2e53f7f8c92d", "type": "subtopic", "title": "Validity and countermodels", "children": [{"id": "b535f1b1-fb6d-4c03-8026-617831598c05", "type": "concept", "title": "Logical consequence"}, {"id": "b3abf112-fa15-4233-a6b5-69b8b1baf9d8", "type": "concept", "title": "Countermodels"}, {"id": "edeb76aa-68f4-4942-b6cd-9723476a7323", "type": "concept", "title": "Model construction"}, {"id": "60b3dec2-e071-4305-a043-8dc761fadcfc", "type": "concept", "title": "Semantic entailment"}], "description": "Validity is tested by all models; invalidity is shown by one carefully built countermodel."}]}, {"id": "d5cea64d-d3f4-4a73-bd7b-136ffba88a46", "type": "topic", "title": "Soundness, Completeness, Compactness, and Limits of Formal Systems", "description": "Introduce the big theorems that connect proof, truth, and the limits of formalization.", "children": [{"id": "b617b91b-4abc-4bac-9dac-4181c31b9c61", "type": "subtopic", "title": "Soundness", "children": [{"id": "7eb7c951-102c-4334-b79f-7b74bcc08b43", "type": "concept", "title": "Rule soundness"}, {"id": "96f72aa2-8f92-4fdf-9e54-1567ccf98577", "type": "concept", "title": "Induction on proof length"}, {"id": "4086734b-12a5-46ea-a0e1-fd04f1870f9b", "type": "concept", "title": "No false validities"}, {"id": "6dfeaada-a4ae-49c6-930b-9018c945a0ae", "type": "concept", "title": "Reliability of derivation"}], "description": "Soundness explains why proof is truth-preserving: anything derivable is semantically valid."}, {"id": "b8edb8b5-1315-4770-9c26-dffd571e48e4", "type": "subtopic", "title": "Completeness", "children": [{"id": "cc1133c6-8051-4f8a-9711-f642101b1937", "type": "concept", "title": "Henkin idea"}, {"id": "3a5e6405-17f7-4283-8ba5-5d57c3bace06", "type": "concept", "title": "Maximal consistent sets"}, {"id": "e2e4217c-b504-40dc-837c-fe544e732919", "type": "concept", "title": "Proof and truth match"}, {"id": "d08bbce8-20c2-438f-9c12-a31b52e15a6e", "type": "concept", "title": "First-order scope"}], "description": "Completeness explains why enough proof power exists for first-order validities."}, {"id": "8fe4ab66-0e25-4343-be34-423b03f19c95", "type": "subtopic", "title": "Limit results", "children": [{"id": "6ece4f98-a555-4a2d-833d-e09d5062a56c", "type": "concept", "title": "Compactness"}, {"id": "4bab0c20-5ef9-4d24-9c14-8acf0562ab58", "type": "concept", "title": "Lowenheim-Skolem idea"}, {"id": "9b249ff9-a326-4adb-b915-360ae06bebf4", "type": "concept", "title": "Undecidability"}, {"id": "c8b75221-6894-4820-ac7e-171846ffceab", "type": "concept", "title": "Godelian limits"}], "description": "A world-class course should hint at why formal systems are powerful but not omnipotent."}]}, {"id": "ed95e92c-1e43-4101-9954-e268f917c379", "type": "topic", "title": "Set-Theoretic Foundations for Logic", "description": "Supply the set, relation, function, and cardinality tools used in semantics and metatheory.", "children": [{"id": "172a5184-a822-4851-a3bc-353b78b4776a", "type": "subtopic", "title": "Sets, relations, and functions", "children": [{"id": "95ec7db3-9956-4c1c-90df-5cc118cde178", "type": "concept", "title": "Sets and membership"}, {"id": "f27c255b-7f9a-47b1-a480-3d5c3a28307a", "type": "concept", "title": "Cartesian products"}, {"id": "2be364dc-fd2f-452c-8614-b64a4ee3677f", "type": "concept", "title": "Relations"}, {"id": "f2e1802b-56c2-4998-92b3-4e44c3d736ce", "type": "concept", "title": "Functions"}], "description": "These mathematical objects are the language in which model-theoretic semantics is written."}, {"id": "7f57bb23-8e31-4a04-b39d-d8cf34c733fe", "type": "subtopic", "title": "Operations and structure", "children": [{"id": "9e1f7fc5-bc24-4ebb-9b10-cceb4415b15a", "type": "concept", "title": "Union and intersection"}, {"id": "fb573f6b-2b5d-47bc-ac6d-c5b16ae40d91", "type": "concept", "title": "Complement"}, {"id": "656d35b9-ac26-413b-8693-e0f7768b56d0", "type": "concept", "title": "Power set"}, {"id": "0daa087f-62fe-4cec-92ec-a8f1746181c3", "type": "concept", "title": "Restriction and image"}], "description": "Students learn the operations needed to describe domains, extensions, and mappings."}, {"id": "82cc99e7-3516-4041-856d-edb169704f58", "type": "subtopic", "title": "Cardinality and infinity", "children": [{"id": "aa7d312b-5d45-43f5-ae1a-e0f9dabc742c", "type": "concept", "title": "Bijections"}, {"id": "94608612-858d-4d5d-8fc2-e1307da80f6a", "type": "concept", "title": "Countability"}, {"id": "10939342-6d07-4d38-a72e-5eb94eaf84a2", "type": "concept", "title": "Uncountability"}, {"id": "2986f02b-0fba-41e6-840b-15902e748124", "type": "concept", "title": "Infinite structures"}], "description": "Cardinality gives precision to claims about finite, countable, and uncountable domains."}]}, {"id": "4802231b-1b7e-41aa-acfa-a6b405490a1d", "type": "topic", "title": "Modal Logic and Possible Worlds", "description": "Extend classical logic to necessity, possibility, knowledge, obligation, and counterfactual reasoning.", "children": [{"id": "a90d282a-0060-497f-9429-99bf4ad0d443", "type": "subtopic", "title": "Necessity and possibility", "children": [{"id": "070f1cb3-7cbd-42ed-bedc-a5a183cf00e3", "type": "concept", "title": "Box and diamond"}, {"id": "e9786fc0-4359-42ef-bcc9-4be97951a5df", "type": "concept", "title": "Duality"}, {"id": "dc73f8fa-ca68-4450-8a82-a8a9b4d54f25", "type": "concept", "title": "Accessibility"}, {"id": "08d62331-072f-41b8-8b05-85409a48c92c", "type": "concept", "title": "Possible worlds"}], "description": "Modal logic adds operators for what must be true and what could be true."}, {"id": "b31c228f-8ee2-4320-8b5a-4297b33e80bc", "type": "subtopic", "title": "Kripke semantics", "children": [{"id": "a2362fb0-c3c9-459d-a67d-55aa0ad1b370", "type": "concept", "title": "Frames"}, {"id": "373bee89-115a-4da6-b6ae-8fe826460f9c", "type": "concept", "title": "Valuation"}, {"id": "edffac32-9ef0-4ecd-be84-adad8861aa6d", "type": "concept", "title": "Truth at a world"}, {"id": "d79c587e-50f0-4151-9146-eae0ad814d3e", "type": "concept", "title": "Validity on a frame"}], "description": "Frames and models make modal reasoning precise across different accessibility relations."}, {"id": "caed872d-380b-4aef-aa1d-30cc826e21d0", "type": "subtopic", "title": "Philosophical modalities", "children": [{"id": "0972e149-f039-4870-8329-69960b25f6c8", "type": "concept", "title": "Metaphysical modality"}, {"id": "93f28234-be04-4c28-a32b-173fcfe22fdc", "type": "concept", "title": "Epistemic logic"}, {"id": "18dc0766-cba1-4e40-a0cf-be487b636780", "type": "concept", "title": "Deontic logic"}, {"id": "4dd5443b-0684-4024-b5e6-4257d2ad6105", "type": "concept", "title": "Counterfactuals"}], "description": "Modal tools apply to metaphysics, epistemology, ethics, and language."}]}, {"id": "7b7e61dc-208a-456e-a31f-81ebee6ba2e1", "type": "topic", "title": "Nonclassical Logics: Intuitionistic, Many-Valued, Paraconsistent, and Free Logic", "description": "Show why philosophers and mathematicians sometimes revise classical assumptions.", "children": [{"id": "ee7cbcc3-f16e-4656-9438-6925fe4febd7", "type": "subtopic", "title": "Motivations for nonclassical logic", "children": [{"id": "a100e546-3e5b-4fe5-b09a-2356ca9a4730", "type": "concept", "title": "Constructive proof"}, {"id": "e207eef8-370b-48e2-a499-689e6dd23f58", "type": "concept", "title": "Vagueness"}, {"id": "c45c9bfb-3a2c-4612-a136-2